using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// --- Notes store (shared state for the note-taking tool) ---
var notes = new List<string>();

// --- Tool definitions ---

[Description("Search the web for a query and return a list of result snippets. Use this to find information about a topic.")]
string WebSearch(
    [Description("The search query string")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    // Use DuckDuckGo's instant-answer API (no key required)
    var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
    var json = http.GetStringAsync(url).GetAwaiter().GetResult();

    using var doc = JsonDocument.Parse(json);
    var root = doc.RootElement;
    var results = new List<string>();

    // Abstract / instant answer
    var abs = root.GetProperty("Abstract").GetString();
    if (!string.IsNullOrWhiteSpace(abs))
        results.Add($"[Summary] {abs}");

    // Related topics
    if (root.TryGetProperty("RelatedTopics", out var topics))
    {
        foreach (var topic in topics.EnumerateArray().Take(8))
        {
            if (topic.TryGetProperty("Text", out var text) &&
                !string.IsNullOrWhiteSpace(text.GetString()))
            {
                results.Add(text.GetString()!);
            }
        }
    }

    return results.Count > 0
        ? string.Join("\n\n", results)
        : "No results found. Try rephrasing the query.";
}

[Description("Save a research note. Use this to record important findings so you can reference them in your final summary.")]
string SaveNote(
    [Description("The note content to save")] string note)
{
    notes.Add(note);
    return $"Note #{notes.Count} saved.";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0) return "No notes saved yet.";
    return string.Join("\n---\n",
        notes.Select((n, i) => $"Note #{i + 1}: {n}"));
}

// --- Build the AI chat pipeline with tools ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()      // auto-invoke tools
    .Build();

var tools = new[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- System prompt ---
var systemPrompt = """
    You are a research agent. Given a topic, you:
    1. Search the web multiple times with varied queries to gather broad information.
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information, retrieve your notes and produce a
       well-structured summary with key facts, organized under clear headings.
    Be thorough — perform at least 3 different searches before summarising.
    """;

// --- Interactive loop ---
Console.WriteLine("🔍 Research Agent ready. Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research this topic and give me a comprehensive summary: {topic}"),
    };

    Console.WriteLine("\n⏳ Researching…\n");

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();

    // Clear notes for next research session
    notes.Clear();
    Console.WriteLine();
}

